
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_k_exp4_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_k_exp4", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([8.960557247141473e+01, 8.688672160917928e+01, 8.320984627261744e+01, 7.837503253529195e+01, 7.227412776915671e+01, 6.501940373916445e+01, 5.701984258942094e+01, 4.841237969692997e+01, 3.643074422463377e+01, 1.946899438741094e+01, 8.356342305076044e+00, 2.594305613289260e+00, 1.693620392790660e+00, 1.477901728908614e+00, 1.077389347539706e+00, 3.811864162354856e-01, 7.864135359936562e-02, 8.736805628757531e-03, 3.979344551012722e-04, 4.988438616201653e-06]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


